using System;using System.IO;using System.Drawing;using System.Drawing.Printing;using System.Reflection;using System.Windows.Forms;using EanEtikety;
class PrintCalibrationTests {
 static int checks;static string dir;static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
 static T Field<T>(object value,string name){return (T)value.GetType().GetField(name,Hidden).GetValue(value);}
 static object Call(object value,string name,params object[] args){return value.GetType().GetMethod(name,Hidden).Invoke(value,args);}
 static void Wait(PrintPanel panel,Action start){int n=panel.PreviewBuilds;start();var clock=System.Diagnostics.Stopwatch.StartNew();while(panel.PreviewBuilds==n){Application.DoEvents();System.Threading.Thread.Sleep(2);if(clock.ElapsedMilliseconds>30000)throw new Exception("Preview timeout: "+Field<Label>(panel,"info").Text);}Check(panel.Ready,"corrected preview remains available");}
 static void Ui(){using(var form=new Form{Size=new Size(1000,700),Location=new Point(-20000,-20000),StartPosition=FormStartPosition.Manual})using(var panel=new PrintPanel(Label())){
  string file=Path.Combine(dir,"ui.xml");panel.LoadProfiles(file);form.Controls.Add(panel);Wait(panel,()=>form.Show());Wait(panel,()=>panel.SelectPrinter("Microsoft Print to PDF"));
  var sx=Field<NumericUpDown>(panel,"scaleX");var sy=Field<NumericUpDown>(panel,"scaleY");Check(sx!=null&&sy!=null,"direct scale controls exist");Wait(panel,()=>sx.Value=103);Wait(panel,()=>sy.Value=98);Field<TextBox>(panel,"profileName").Text="Calibrated";Call(panel,"SaveMediaProfile");
  Wait(panel,()=>sx.Value=100);Wait(panel,()=>sy.Value=100);Field<TextBox>(panel,"profileName").Text="Plain";Call(panel,"SaveMediaProfile");var profiles=Field<ModernComboBox>(panel,"mediaProfiles");Wait(panel,()=>profiles.SelectedIndex=0);Check(sx.Value==103&&sy.Value==98,"UI profile restores independent scales");Wait(panel,()=>profiles.SelectedIndex=1);Check(sx.Value==100&&sy.Value==100,"another medium has unit correction");
  var activePage=Field<PageSettings>(panel,"selectedPage");activePage.PrinterResolution=new PrinterResolution{Kind=PrinterResolutionKind.Custom,X=203,Y=203};activePage.PaperSource=new PaperSource{RawKind=259,SourceName="Custom source"};
  var baseline=new PrinterProfile{Printer="Microsoft Print to PDF",Name="Measured",Width=236,Height=177,X=3,Y=2,ScaleX=1.05,ScaleY=.95};var target=CalibrationTarget.Create(60,45);using(var testPanel=(PrintPanel)Call(panel,"CreateCalibrationPanel",target,baseline)){var raw=Field<PrinterProfile>(testPanel,"requestedProfile");Check(raw.X==0&&raw.Y==0&&raw.ScaleX==1&&raw.ScaleY==1,"calibration reprints always use an uncorrected baseline");Check(!Field<ModernButton>(testPanel,"calibrationLaunch").Enabled,"no recursive wizard");var preserved=Field<PageSettings>(testPanel,"selectedPage");Check(preserved!=null&&preserved.PrinterResolution.X==203&&preserved.PaperSource.RawKind==259,"target preserves active driver setup");Check(!ReferenceEquals(preserved,activePage),"target driver page is an independent clone");Check(!Field<ModernComboBox>(testPanel,"printers").Enabled&&!Field<NumericUpDown>(testPanel,"scaleX").Enabled&&!Field<ModernButton>(testPanel,"driverProperties").Enabled,"target setup cannot diverge before print");Check(!testPanel.ConfigurePrinter(dialog=>{throw new Exception("locked driver must never open");}),"target driver properties route is locked");testPanel.SelectPrinter("Other printer");Check(Field<PrinterSettings>(testPanel,"selectedPrinter").PrinterName==baseline.Printer,"target printer route is locked");}
  var captured=(PrinterProfile)Call(panel,"CurrentMediaProfile");captured.Name="Measured and saved";var correction=PrintCalibration.FromMeasurements(target,7,4,51,43);Wait(panel,()=>Call(panel,"ApplyMeasuredCalibration",captured,correction));var persisted=new PrinterProfileStore(file).Find(captured.Printer,captured.Name);Near(persisted.ScaleX,correction.ScaleX,"measured scale saved for exact media");Near((double)sx.Value/100,correction.ScaleX,"measured scale becomes active");
  string blocked=Path.Combine(dir,"cannot-save-profile");File.WriteAllText(blocked,"x");var badStore=new PrinterProfileStore(Path.Combine(blocked,"profiles.xml"));typeof(PrintPanel).GetField("profiles",Hidden).SetValue(panel,badStore);decimal before=sx.Value;bool failed=false;try{Call(panel,"ApplyMeasuredCalibration",captured,new PrintCalibration());}catch(TargetInvocationException){failed=true;}Check(failed&&sx.Value==before,"failed profile save preserves active calibration");
  Check(Field<Label>(panel,"paperInfo").Text.Contains(Loc.T("Skutočne vložené médium: neoverené.")),"print UI distinguishes configured and actual media");Check(Field<ModernButton>(panel,"diagnosticsButton").Enabled,"fresh print diagnostics accessible");
  form.Close();
 }}
 static void Wizard(){var target=CalibrationTarget.Create(60,40);int saves=0,prints=0;PrintCalibration saved=null;
  using(var dialog=new PrintCalibrationDialog(target,()=>prints++,c=>{saves++;saved=c;})){
   Check(!(bool)Call(dialog,"TryApply")&&saves==0,"unconfirmed measurements never apply");Field<CheckBox>(dialog,"confirmed").Checked=true;Field<NumericUpDown>(dialog,"measuredWidth").Value=1;Check(!(bool)Call(dialog,"TryApply")&&saves==0,"implausible measurements never save");Field<NumericUpDown>(dialog,"measuredWidth").Value=51;Field<NumericUpDown>(dialog,"measuredX").Value=7.1m;Check((bool)Call(dialog,"TryApply")&&saves==1,"confirmed measured calibration saves once");Near(saved.X,5-(50.0/51)*7.1,"wizard computes baseline correction");Check(prints==0,"wizard never submits a print automatically");
  }
  foreach(string language in Loc.Codes)foreach(float factor in new[]{1f,1.25f,1.5f,2f}){Loc.Language=language;using(var dialog=new PrintCalibrationDialog(target,()=>{},c=>{})){dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-20000,-20000);dialog.Show();dialog.Scale(new SizeF(factor,factor));dialog.ClientSize=new Size((int)(470*factor),(int)(380*factor));Application.DoEvents();var apply=Field<ModernButton>(dialog,"apply");var scroll=(Panel)dialog.Controls[0];scroll.ScrollControlIntoView(apply);Application.DoEvents();var rect=scroll.RectangleToClient(apply.RectangleToScreen(apply.ClientRectangle));Check(rect.Bottom<=scroll.ClientSize.Height&&rect.Top>=0,"apply reachable by scrolling "+language+" "+factor);Check(Field<NumericUpDown>(dialog,"measuredX").Width>=100*factor,"measurement control width "+language+" "+factor);Check(language=="sk"||Loc.T("Sprievodca kalibráciou…")!="Sprievodca kalibráciou…","wizard translation "+language);if(language=="sk"&&factor==1){scroll.AutoScrollPosition=Point.Empty;using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,dialog.ClientRectangle);image.Save(Path.Combine(dir,"wizard-small.png"));}}dialog.Close();}}
  Loc.Language="sk";
 }
 static void Diagnostics(){using(var d=new LabelPrintDocument(Label())){d.PrinterSettings.PrinterName="Microsoft Print to PDF";d.DefaultPageSettings.PaperSize=new PaperSize("PRIVATE-MEDIA-NAME",827,1169);d.ScaleX=1.03;d.ScaleY=.98;d.OffsetX=2.3;var report=PrintDiagnostics.Capture(d,d.DefaultPageSettings,3);var original=System.Threading.Thread.CurrentThread.CurrentCulture;string text;try{System.Threading.Thread.CurrentThread.CurrentCulture=new System.Globalization.CultureInfo("sk-SK");text=report.Format();}finally{System.Threading.Thread.CurrentThread.CurrentCulture=original;}
   Check(text.Contains("Scale=1.03,0.98")&&text.Contains("Repeats=3")&&text.Contains("ActualLoadedMedia=unverified"),"invariant numeric facts and unverified physical medium");Check(text.Contains("HardMarginsMm=")&&text.Contains("PrintableAreaMm=")&&text.Contains("ConfiguredDriverMediaMm="),"driver facts are separate");Check(!text.Contains("PRIVATE")&&!text.Contains("Microsoft Print")&&!text.Contains("MMMM")&&!text.Contains(dir),"diagnostics omit private identifiers and content");Near(report.CorrectedDocument.Width,d.WidthMm*1.03,"diagnostic corrected size");
   string logDir=Path.Combine(dir,"logs");Directory.CreateDirectory(logDir);File.WriteAllText(Path.Combine(logDir,"application.log"),new string('a',DiagnosticLog.MaxBytes-5));string id=DiagnosticLog.WritePrintTo(logDir,report,"submitted",new IOException("PRIVATE-ERROR-PATH"));Check(id!=null&&File.Exists(Path.Combine(logDir,"application.log.1")),"print diagnostics use bounded rotation");string log=File.ReadAllText(Path.Combine(logDir,"application.log"));Check(log.Contains("Operation=print-submitted")&&log.Contains("ActualLoadedMedia=unverified")&&!log.Contains("PRIVATE"),"safe submit status and no exception message");string blocked=Path.Combine(dir,"blocked-log");File.WriteAllText(blocked,"x");Check(DiagnosticLog.WritePrintTo(blocked,report,"failed",null)==null,"logging failure does not interrupt output");
  }}
 static void Legacy(){var p=ProjectXml.Decode<PrinterProfile>("<PrinterProfile><Printer>P</Printer><Paper>A4</Paper><Width>827</Width><Height>1169</Height><X>2</X><Y>-1</Y></PrinterProfile>");var sx=typeof(PrinterProfile).GetField("ScaleX");var sy=typeof(PrinterProfile).GetField("ScaleY");Check(sx!=null&&sy!=null,"Legacy profiles need independent scale fields with unit defaults");Check((double)sx.GetValue(p)==1&&(double)sy.GetValue(p)==1&&p.X==2&&p.Y==-1,"Missing XML scale must preserve old offset and physical dimensions");}
 static void Near(double a,double b,string name){Check(Math.Abs(a-b)<.001,name+": "+a+" vs "+b);}
 static void Reject(Action action,string name){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}Check(rejected,name);}
 static void Model(){
  var target=CalibrationTarget.Create(60,40);Near(target.AnchorX,5,"target X origin");Near(target.SpanX,50,"target X reference");Near(target.SpanY,30,"target Y reference");
  var c=PrintCalibration.FromMeasurements(target,7.1,3.9,51,29.4);Near(c.ScaleX,50.0/51,"X scale");Near(c.ScaleY,30.0/29.4,"Y scale");Near(c.X,5-c.ScaleX*7.1,"X offset");Near(c.Y,5-c.ScaleY*3.9,"Y offset");
  var bounds=c.Transform(new RectangleF(10,20,30,40));Near(bounds.X,10*c.ScaleX+c.X,"transform origin");Near(bounds.Width,30*c.ScaleX,"transform width");
  Reject(()=>PrintCalibration.FromMeasurements(target,5,5,0,30),"zero measured span");Reject(()=>PrintCalibration.FromMeasurements(target,double.NaN,5,50,30),"NaN measurement");Reject(()=>PrintCalibration.FromMeasurements(target,5,5,10,30),"implausible scale");Reject(()=>CalibrationTarget.Create(11,40),"undersized target");
  var small=CalibrationTarget.Create(12,12);Check(small.SpanX>7&&small.SpanY>7,"small target retains measurable spans");Check(CalibrationTarget.Create(210,297).SpanX==100,"large targets cap span");using(var d=new LabelPrintDocument(target.Label))using(var b=new Bitmap(600,400)){b.SetResolution(254,254);using(var g=Graphics.FromImage(b)){g.Clear(Color.White);d.RenderPage(g,0);}foreach(var mark in new[]{new Point(50,50),new Point(550,50),new Point(50,350)})Check(b.GetPixel(mark.X,mark.Y).R<150,"target crosshair at reference coordinate "+mark);b.Save(Path.Combine(dir,"calibration-target.png"));}
  string file=Path.Combine(dir,"scale-profiles.xml");var store=new PrinterProfileStore(file);var p=new PrinterProfile{Printer="P",Name="A",Width=236,Height=157,X=c.X,Y=c.Y,ScaleX=c.ScaleX,ScaleY=c.ScaleY};store.Save(p);store.Save(new PrinterProfile{Printer="P",Name="B",Width=394,Height=591});var loaded=new PrinterProfileStore(file);Near(loaded.Find("P","A").ScaleX,c.ScaleX,"scale roundtrip");Near(loaded.Find("P","B").ScaleX,1,"independent media");
  foreach(double invalid in new[]{0.0,-1,double.NaN,double.PositiveInfinity,.79,1.21}){p.ScaleX=invalid;Reject(()=>store.Save(p),"invalid profile scale");}Check(new PrinterProfileStore(file).Profiles.Count==2,"invalid save is atomic");
 }
 static LabelSettings Label(){var l=LabelSettings.Default();l.HideBarcode=true;l.Texts.Clear();l.Symbols.Clear();l.Texts.Add(new TextItem{Text="MMMM",X=15,Y=12,Width=25,Height=12,Size=16});return l;}
 static Rectangle Ink(Bitmap b){int left=b.Width,top=b.Height,right=-1,bottom=-1;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).R<150){left=Math.Min(left,x);right=Math.Max(right,x);top=Math.Min(top,y);bottom=Math.Max(bottom,y);}return Rectangle.FromLTRB(left,top,right+1,bottom+1);}
 static void Geometry(){var label=Label();string xml=ProjectXml.Encode(label);using(var d=new LabelPrintDocument(label)){d.IgnoreDriverMargins=true;Rectangle baseline=Rectangle.Empty;foreach(bool corrected in new[]{false,true})using(var b=new Bitmap(900,700)){b.SetResolution(254,254);d.ScaleX=corrected?1.1:1;d.ScaleY=corrected?.9:1;d.OffsetX=corrected?2:0;d.OffsetY=corrected?3:0;using(var g=Graphics.FromImage(b)){g.Clear(Color.White);d.RenderPrinterPage(g,0,new RectangleF(0,0,400,300),4,6,false);}var ink=Ink(b);if(!corrected)baseline=ink;else{Check(Math.Abs(ink.Width-baseline.Width*1.1)<3&&Math.Abs(ink.Height-baseline.Height*.9)<3,"raster uses independent scales");Check(Math.Abs(ink.X-((baseline.X+4*.254*10)*1.1+20-4*.254*10))<3,"hard margin and physical offset order");}b.Save(Path.Combine(dir,corrected?"corrected.png":"baseline.png"));}
   var r=d.LabelBounds(0);Near(r.X,2,"label offset unscaled");Near(r.Width,label.Width*1.1,"corrected label bounds");d.PrinterSettings.PrinterName="Microsoft Print to PDF";var first=d.InspectOutput().Fingerprint;d.ScaleX=1.11;Check(d.InspectOutput().Fingerprint!=first,"scale invalidates review approval");Check(!d.ContentFits(new RectangleF(0,0,10,10)),"clipping check sees corrected content");Check(!d.FitsPaper(new Rectangle(0,0,240,180)),"scaled page does not fit nominal label media");using(var b=new Bitmap(900,700)){b.SetResolution(254,254);using(var g=Graphics.FromImage(b)){g.Clear(Color.White);g.SetClip(new Rectangle(0,0,180,700));d.RenderPrinterPage(g,0,new RectangleF(0,0,400,300),4,6,false);}Check(Ink(b).Right<=180,"calibrated output preserves the native clip");}
  }Check(ProjectXml.Encode(label)==xml,"printing never mutates saved document dimensions");}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Legacy();Model();Geometry();Ui();Wizard();Diagnostics();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+checks+" calibration checks");}catch(Exception ex){File.WriteAllText(Path.Combine(dir,"failed.txt"),ex.ToString());Environment.ExitCode=1;}}
}
